insert into public.recipes (id, name, minutes, difficulty, servings, tools, steps, image_key, source) values
  ('kimchi_fried_rice', '김치볶음밥', 15, 1, 1, '{}'::text[], '[{"text":"김치와 햄, 양파를 잘게 썬다."},{"text":"기름에 대파를 볶다가 김치·햄·양파를 넣고 3분 볶는다."},{"text":"고춧가루·간장을 넣고 밥을 넣어 고루 볶는다."},{"text":"참기름을 두르고 달걀프라이를 올린다."}]'::jsonb, null, 'manual'),
  ('soy_egg_rice', '간장계란밥', 5, 1, 1, '{}'::text[], '[{"text":"달걀프라이를 반숙으로 부친다."},{"text":"따뜻한 밥에 버터·간장·참기름을 넣고 달걀을 올린다."},{"text":"김을 부숴 올리고 비벼 먹는다."}]'::jsonb, null, 'manual'),
  ('tuna_mayo_rice', '참치마요덮밥', 10, 1, 1, '{}'::text[], '[{"text":"참치의 기름을 뺀다."},{"text":"양파를 다져 참치·마요네즈와 섞는다."},{"text":"밥 위에 간장·설탕을 섞은 소스를 뿌리고 참치마요와 김을 올린다."}]'::jsonb, null, 'manual'),
  ('canned_ham_mayo_rice', '스팸마요덮밥', 15, 1, 1, '{}'::text[], '[{"text":"캔햄을 깍둑썰어 노릇하게 굽는다."},{"text":"달걀은 스크램블로 익힌다."},{"text":"간장·설탕을 졸여 소스를 만든다."},{"text":"밥에 햄·달걀을 올리고 소스·마요네즈·김을 뿌린다."}]'::jsonb, null, 'manual'),
  ('egg_fried_rice', '계란볶음밥', 10, 1, 1, '{}'::text[], '[{"text":"기름에 송송 썬 대파를 볶아 파기름을 낸다."},{"text":"달걀을 풀어 넣고 반쯤 익으면 밥을 넣는다."},{"text":"간장(굴소스)을 팬 가장자리에 눌려 넣고 볶은 뒤 소금으로 간한다."}]'::jsonb, null, 'manual'),
  ('shrimp_fried_rice', '새우볶음밥', 15, 1, 1, '{}'::text[], '[{"text":"새우는 해동해 물기를 닦는다."},{"text":"파기름에 새우와 채소를 볶는다."},{"text":"달걀과 밥을 넣어 볶고 굴소스로 간한다."}]'::jsonb, null, 'manual'),
  ('omurice', '오므라이스', 25, 2, 1, '{}'::text[], '[{"text":"양파·당근·햄을 잘게 썰어 볶는다."},{"text":"밥과 케첩 절반을 넣어 볶음밥을 만든다."},{"text":"달걀을 소금 간해 얇게 부치고 볶음밥을 감싼다."},{"text":"남은 케첩을 뿌린다."}]'::jsonb, null, 'manual'),
  ('curry_rice', '카레라이스', 35, 1, 2, '{}'::text[], '[{"text":"감자·당근·양파·고기를 깍둑썬다."},{"text":"기름에 고기와 채소를 볶는다."},{"text":"물 500ml를 붓고 감자가 익을 때까지 끓인다.","timerSec":900},{"text":"불을 줄이고 카레가루를 풀어 걸쭉하게 끓인다."}]'::jsonb, null, 'manual'),
  ('bibimbap', '비빔밥', 20, 1, 1, '{}'::text[], '[{"text":"채소는 각각 데치거나 볶아 소금 간한다."},{"text":"다진 소고기는 간장에 볶는다."},{"text":"밥 위에 나물·고기·달걀프라이를 올리고 고추장·참기름을 넣어 비빈다."}]'::jsonb, null, 'manual'),
  ('kimbap', '김밥', 40, 2, 2, '{}'::text[], '[{"text":"밥에 참기름·소금을 섞는다."},{"text":"달걀은 지단을 부쳐 길게 썰고, 햄·당근은 볶고 시금치는 데친다."},{"text":"김 위에 밥을 얇게 펴고 속재료를 올려 단단히 만다."},{"text":"참기름을 바르고 썬다."}]'::jsonb, null, 'manual'),
  ('salmon_rice_bowl', '연어덮밥', 15, 1, 1, '{}'::text[], '[{"text":"간장·맛술·설탕을 한소끔 끓여 식힌다."},{"text":"양파는 얇게 채 썰어 찬물에 담근다."},{"text":"밥 위에 깻잎·양파·연어를 올리고 소스를 뿌린다."}]'::jsonb, null, 'manual'),
  ('beef_rice_bowl', '규동', 15, 1, 1, '{}'::text[], '[{"text":"물 100ml에 간장·맛술·설탕을 넣고 끓인다."},{"text":"양파를 넣어 숨이 죽으면 소고기를 넣고 익힌다."},{"text":"밥 위에 올리고 대파와 달걀노른자를 얹는다."}]'::jsonb, null, 'manual'),
  ('chicken_mayo_rice', '치킨마요덮밥', 20, 1, 1, '{}'::text[], '[{"text":"치킨너겟은 굽고, 닭가슴살은 한입 크기로 썰어 굽는다."},{"text":"달걀은 스크램블한다."},{"text":"간장·설탕·물을 졸여 소스를 만든다."},{"text":"밥에 닭·달걀을 올리고 소스·마요네즈·김을 뿌린다."}]'::jsonb, null, 'manual'),
  ('bean_sprout_rice', '콩나물밥', 35, 1, 2, '{}'::text[], '[{"text":"쌀을 씻어 30분 불린다."},{"text":"냄비에 쌀, 물(평소보다 적게), 콩나물, 소고기를 올린다."},{"text":"센 불로 끓이다 약불로 줄여 밥을 짓는다.","timerSec":900},{"text":"간장·대파·참기름·고춧가루로 양념장을 만들어 비빈다."}]'::jsonb, null, 'manual'),
  ('kimchi_stew', '김치찌개', 25, 1, 2, '{}'::text[], '[{"text":"냄비에 고기(또는 참치·햄)와 김치를 넣고 볶는다."},{"text":"물 400ml를 붓고 끓인다.","timerSec":600},{"text":"두부·양파·다진 마늘·고춧가루를 넣는다."},{"text":"5분 더 끓이고 대파를 올린다.","timerSec":300}]'::jsonb, null, 'manual'),
  ('doenjang_stew', '된장찌개', 25, 1, 2, '{}'::text[], '[{"text":"멸치로 육수를 낸다 (없으면 물)."},{"text":"된장을 풀고 감자를 먼저 넣어 끓인다."},{"text":"애호박·양파·두부를 넣고 끓인다.","timerSec":420},{"text":"다진 마늘·청양고추·대파를 넣고 마무리한다."}]'::jsonb, null, 'manual'),
  ('sundubu_stew', '순두부찌개', 20, 1, 1, '{}'::text[], '[{"text":"뚝배기에 기름·고춧가루·다진 마늘을 볶아 고추기름을 낸다."},{"text":"물 250ml와 채소·바지락을 넣고 끓인다."},{"text":"순두부를 크게 떠 넣고 간장으로 간한다.","timerSec":300},{"text":"달걀을 깨 넣고 대파를 올린다."}]'::jsonb, null, 'manual'),
  ('gochujang_stew', '고추장찌개', 30, 1, 2, '{}'::text[], '[{"text":"고기를 볶다가 물 500ml를 붓는다."},{"text":"고추장·고춧가루를 풀고 감자를 넣어 끓인다."},{"text":"감자가 반쯤 익으면 애호박·양파를 넣는다.","timerSec":600},{"text":"다진 마늘과 대파를 넣어 마무리한다."}]'::jsonb, null, 'manual'),
  ('budae_jjigae', '부대찌개', 30, 1, 2, '{}'::text[], '[{"text":"고춧가루·고추장·간장·다진 마늘로 양념장을 만든다."},{"text":"냄비에 햄·소시지·김치·두부·채소를 둘러 담는다."},{"text":"물 600ml와 양념장을 넣고 끓인다.","timerSec":600},{"text":"라면 사리와 치즈를 넣어 면이 익으면 먹는다."}]'::jsonb, null, 'manual'),
  ('kimchi_jjim', '김치찜', 60, 2, 2, '{}'::text[], '[{"text":"냄비 바닥에 양파를 깔고 통김치와 고기를 올린다."},{"text":"고춧가루·설탕·다진 마늘을 뿌리고 물 400ml를 붓는다."},{"text":"뚜껑을 덮고 중약불에서 푹 찐다.","timerSec":2400},{"text":"대파를 올려 5분 더 끓인다."}]'::jsonb, null, 'manual'),
  ('miyeok_guk', '미역국', 30, 1, 2, '{}'::text[], '[{"text":"미역을 물에 20분 불려 헹군다."},{"text":"참기름에 고기(또는 조개)와 미역을 볶는다."},{"text":"물 800ml를 붓고 끓인다.","timerSec":1200},{"text":"간장·다진 마늘로 간한다."}]'::jsonb, null, 'manual'),
  ('kongnamul_guk', '콩나물국', 15, 1, 2, '{}'::text[], '[{"text":"멸치 육수 600ml를 낸다."},{"text":"콩나물을 넣고 뚜껑을 덮어 끓인다.","timerSec":300},{"text":"다진 마늘·대파·청양고추를 넣고 소금으로 간한다."}]'::jsonb, null, 'manual'),
  ('egg_soup', '계란국', 10, 1, 2, '{}'::text[], '[{"text":"멸치·다시마로 육수를 낸다 (없으면 물)."},{"text":"끓는 육수에 달걀물을 둘러 붓는다."},{"text":"간장·소금으로 간하고 대파를 넣는다."}]'::jsonb, null, 'manual'),
  ('beef_radish_soup', '소고기무국', 40, 1, 2, '{}'::text[], '[{"text":"무는 나박썰기한다."},{"text":"참기름에 소고기와 무를 볶는다."},{"text":"물 800ml를 붓고 무가 투명해질 때까지 끓인다.","timerSec":1200},{"text":"간장·다진 마늘로 간하고 대파를 넣는다."}]'::jsonb, null, 'manual'),
  ('fish_cake_soup', '어묵탕', 25, 1, 2, '{}'::text[], '[{"text":"무·다시마·멸치로 육수를 낸다."},{"text":"어묵을 넣고 끓인다.","timerSec":300},{"text":"간장으로 간하고 대파·청양고추를 넣는다."}]'::jsonb, null, 'manual'),
  ('tteokguk', '떡국', 25, 1, 2, '{}'::text[], '[{"text":"떡을 물에 10분 불린다."},{"text":"고기를 볶다 물 800ml를 붓고 끓인다."},{"text":"떡을 넣어 떠오를 때까지 끓인다.","timerSec":300},{"text":"달걀물·대파를 넣고 간장으로 간한 뒤 김을 올린다."}]'::jsonb, null, 'manual'),
  ('mandu_guk', '만둣국', 15, 1, 2, '{}'::text[], '[{"text":"물 700ml를 끓인다."},{"text":"만두와 떡을 넣고 끓인다.","timerSec":420},{"text":"달걀물·대파를 넣고 간장으로 간한다."}]'::jsonb, null, 'manual'),
  ('clam_soup', '바지락탕', 15, 1, 2, '{}'::text[], '[{"text":"바지락을 소금물에 담가 해감한다."},{"text":"물 600ml에 바지락을 넣고 입이 벌어질 때까지 끓인다.","timerSec":300},{"text":"다진 마늘·대파·청양고추를 넣고 소금으로 간한다."}]'::jsonb, null, 'manual'),
  ('mussel_soup', '홍합탕', 20, 1, 2, '{}'::text[], '[{"text":"홍합의 수염을 떼고 씻는다."},{"text":"물 700ml에 홍합을 넣고 끓인다.","timerSec":420},{"text":"다진 마늘·대파·청양고추를 넣고 간한다."}]'::jsonb, null, 'manual'),
  ('oyster_soup', '굴국', 20, 1, 2, '{}'::text[], '[{"text":"굴을 소금물에 살살 씻는다."},{"text":"무를 넣고 물 600ml를 끓인다."},{"text":"굴·두부를 넣고 한소끔 끓인다.","timerSec":180},{"text":"다진 마늘·대파를 넣고 소금으로 간한다."}]'::jsonb, null, 'manual'),
  ('pollack_stew', '동태찌개', 40, 2, 2, '{}'::text[], '[{"text":"동태를 해동해 손질한다."},{"text":"무를 넣고 물 800ml를 끓인다.","timerSec":600},{"text":"동태·고춧가루·다진 마늘을 넣고 끓인다.","timerSec":600},{"text":"두부·애호박·대파·쑥갓을 넣고 간장으로 간한다."}]'::jsonb, null, 'manual'),
  ('hwangtae_soup', '북엇국', 25, 1, 2, '{}'::text[], '[{"text":"북어채를 물에 살짝 적신다."},{"text":"참기름에 북어채를 볶다가 물 700ml를 붓는다."},{"text":"무를 넣고 뽀얗게 끓인다.","timerSec":600},{"text":"달걀물·대파·다진 마늘을 넣고 간한다."}]'::jsonb, null, 'manual'),
  ('spinach_doenjang_soup', '시금치 된장국', 20, 1, 2, '{}'::text[], '[{"text":"멸치 육수 600ml에 된장을 푼다."},{"text":"시금치와 두부를 넣고 끓인다.","timerSec":300},{"text":"다진 마늘·대파를 넣는다."}]'::jsonb, null, 'manual'),
  ('napa_doenjang_soup', '배추 된장국', 25, 1, 2, '{}'::text[], '[{"text":"배추를 한입 크기로 썬다."},{"text":"멸치 육수에 된장을 풀고 배추를 넣는다."},{"text":"배추가 부드러워질 때까지 끓인다.","timerSec":600},{"text":"다진 마늘·대파를 넣는다."}]'::jsonb, null, 'manual'),
  ('chicken_baeksuk', '닭백숙', 70, 2, 2, '{}'::text[], '[{"text":"닭을 씻고 기름을 떼어 낸다."},{"text":"냄비에 닭·마늘·생강·대파와 물을 넉넉히 넣고 끓인다.","timerSec":3000},{"text":"닭을 건져 소금에 찍어 먹는다."},{"text":"남은 국물에 불린 쌀을 넣어 죽을 쑨다."}]'::jsonb, null, 'manual'),
  ('jeyuk_bokkeum', '제육볶음', 25, 1, 1, '{}'::text[], '[{"text":"고추장·고춧가루·간장·설탕·다진 마늘로 양념을 만든다."},{"text":"고기를 양념에 10분 재운다."},{"text":"센 불에 고기를 볶다가 채소를 넣고 익힌다."},{"text":"참기름을 두르고 마무리한다."}]'::jsonb, null, 'manual'),
  ('bulgogi', '소불고기', 30, 1, 1, '{}'::text[], '[{"text":"간장·설탕·다진 마늘·참기름·후추로 양념을 만든다."},{"text":"고기를 양념에 20분 재운다."},{"text":"채소와 함께 센 불에 볶는다."}]'::jsonb, null, 'manual'),
  ('samgyeopsal_gui', '삼겹살구이', 20, 1, 1, '{}'::text[], '[{"text":"팬을 달궈 고기를 굽는다."},{"text":"마늘과 김치를 고기 기름에 함께 굽는다."},{"text":"쌈채소에 고기와 쌈장을 올려 먹는다."}]'::jsonb, null, 'manual'),
  ('kongbul', '콩불', 25, 1, 2, '{}'::text[], '[{"text":"양념을 만들어 고기에 버무린다."},{"text":"팬에 콩나물을 깔고 양념한 고기와 양파를 올린다."},{"text":"뚜껑을 덮고 중불에서 익힌다.","timerSec":420},{"text":"대파를 넣고 섞으며 볶는다."}]'::jsonb, null, 'manual'),
  ('pork_ribs_jjim', '돼지갈비찜', 70, 2, 2, '{}'::text[], '[{"text":"갈비를 찬물에 담가 핏물을 뺀 뒤 한 번 데친다."},{"text":"간장·설탕·올리고당·다진 마늘로 양념을 만든다."},{"text":"갈비와 양념, 물 500ml를 넣고 끓인다.","timerSec":1800},{"text":"감자·당근·양파를 넣고 졸인다.","timerSec":1200}]'::jsonb, null, 'manual'),
  ('dakgalbi', '닭갈비', 30, 1, 2, '{}'::text[], '[{"text":"닭고기를 양념에 20분 재운다."},{"text":"팬에 고구마·양배추·떡을 깔고 닭을 올린다."},{"text":"뒤적이며 닭과 고구마가 익을 때까지 볶는다.","timerSec":720},{"text":"대파·깻잎을 넣고 마무리한다."}]'::jsonb, null, 'manual'),
  ('dakbokkeumtang', '닭볶음탕', 50, 2, 2, '{}'::text[], '[{"text":"닭을 한 번 데쳐 헹군다."},{"text":"양념과 물 500ml, 닭을 넣고 끓인다."},{"text":"감자·당근을 넣고 중불로 끓인다.","timerSec":1200},{"text":"양파·대파를 넣고 국물을 졸인다.","timerSec":600}]'::jsonb, null, 'manual'),
  ('chicken_veg_stir', '닭가슴살 채소볶음', 20, 1, 1, '{}'::text[], '[{"text":"닭가슴살과 채소를 한입 크기로 썬다."},{"text":"마늘 기름에 닭을 먼저 볶는다."},{"text":"채소를 넣고 굴소스로 간한다."}]'::jsonb, null, 'manual'),
  ('chicken_breast_salad', '닭가슴살 샐러드', 15, 1, 1, '{}'::text[], '[{"text":"닭가슴살을 삶거나 구워 찢는다."},{"text":"채소를 씻어 물기를 뺀다."},{"text":"오일·식초·꿀·소금·후추로 드레싱을 만들어 뿌린다."}]'::jsonb, null, 'manual'),
  ('air_fryer_wings', '에어프라이어 닭날개구이', 30, 1, 1, array['air_fryer']::text[], '[{"text":"닭날개에 칼집을 내고 소금·후추로 밑간한다."},{"text":"에어프라이어 180도에서 굽는다.","timerSec":900},{"text":"뒤집어서 더 굽는다.","timerSec":600}]'::jsonb, null, 'manual'),
