  ('tangsuyuk', '탕수육', 40, 1, 2, '{}'::text[], '[{"text":"고기를 길쭉하게 썰어 간장·후추로 밑간한다."},{"text":"전분을 물에 불려 가라앉힌 앙금으로 튀김옷을 입힌다."},{"text":"170도 기름에 두 번 튀긴다.","timerSec":480},{"text":"물 200ml·식초·설탕·간장에 채소·파인애플을 끓이고 물전분으로 소스를 만든다."}]'::jsonb, null, 'manual'),
  ('chili_shrimp', '칠리새우', 25, 1, 1, '{}'::text[], '[{"text":"새우에 전분을 묻혀 튀기듯 굽는다."},{"text":"마늘·양파를 볶고 칠리소스(또는 케첩)·설탕·물 2큰술을 끓인다."},{"text":"새우를 넣고 버무린다."}]'::jsonb, null, 'manual'),
  ('beef_steak', '소고기 스테이크', 20, 1, 1, '{}'::text[], '[{"text":"고기를 실온에 30분 두고 소금·후추를 뿌린다."},{"text":"센 불에 앞뒤로 굽는다.","timerSec":240},{"text":"버터·마늘을 넣고 녹은 버터를 끼얹는다."},{"text":"불을 끄고 고기를 쉬게 한다.","timerSec":300},{"text":"아스파라거스·버섯을 같은 팬에 굽는다."}]'::jsonb, null, 'manual'),
  ('hamburg_steak', '함박스테이크', 35, 1, 2, '{}'::text[], '[{"text":"다진 양파를 볶아 식힌다."},{"text":"고기·양파·달걀·빵가루·소금을 치대 둥글넓적하게 빚는다."},{"text":"약불에 뚜껑 덮고 앞뒤로 굽는다.","timerSec":600},{"text":"케첩·굴소스·설탕·물 3큰술로 소스를 끓여 붓는다."}]'::jsonb, null, 'manual'),
  ('fish_sauced_eggplant', '어향가지', 25, 1, 1, '{}'::text[], '[{"text":"가지를 길쭉하게 썰어 전분을 묻혀 굽는다."},{"text":"마늘·파·고기를 볶다가 두반장을 넣는다."},{"text":"간장·식초·설탕·물 100ml를 넣고 끓인다."},{"text":"가지를 넣고 소스를 졸여 입힌다."}]'::jsonb, null, 'manual'),
  ('spanish_mackerel_gui', '삼치구이', 20, 1, 1, '{}'::text[], '[{"text":"삼치에 소금을 뿌려 10분 둔다."},{"text":"껍질 쪽부터 굽는다.","timerSec":300},{"text":"뒤집어 굽는다.","timerSec":240},{"text":"레몬을 곁들인다."}]'::jsonb, null, 'manual'),
  ('yellow_croaker_gui', '조기구이', 20, 1, 1, '{}'::text[], '[{"text":"조기의 비늘을 긁고 칼집을 낸다."},{"text":"기름 두른 팬에 앞뒤로 굽는다.","timerSec":600}]'::jsonb, null, 'manual'),
  ('saury_kimchi_jjim', '꽁치 김치찜', 35, 1, 2, '{}'::text[], '[{"text":"냄비에 김치를 깔고 꽁치를 올린다."},{"text":"고춧가루·마늘·설탕과 꽁치 국물(또는 물 200ml)을 붓는다."},{"text":"뚜껑 덮고 중약불로 졸인다.","timerSec":1200},{"text":"양파·파를 넣고 더 끓인다."}]'::jsonb, null, 'manual'),
  ('fish_jeon', '생선전', 25, 1, 2, '{}'::text[], '[{"text":"생선살을 얇게 포 떠 소금·후추를 뿌린다."},{"text":"밀가루를 얇게 묻히고 달걀물을 입힌다."},{"text":"약불에 앞뒤로 부친다.","timerSec":360}]'::jsonb, null, 'manual'),
  ('abalone_butter', '전복 버터구이', 15, 1, 1, '{}'::text[], '[{"text":"전복을 솔로 씻어 칼집을 낸다."},{"text":"버터에 마늘을 볶고 전복을 굽는다.","timerSec":240},{"text":"간장을 둘러 마무리한다."}]'::jsonb, null, 'manual'),
  ('scallop_butter', '가리비 버터구이', 15, 1, 1, '{}'::text[], '[{"text":"가리비를 씻어 물기를 닦는다."},{"text":"버터에 마늘을 볶다가 가리비를 굽는다.","timerSec":180},{"text":"간장을 두르고 파슬리를 뿌린다."}]'::jsonb, null, 'manual'),
  ('mussel_wine_steam', '홍합 술찜', 20, 1, 1, '{}'::text[], '[{"text":"홍합의 수염을 떼고 씻는다."},{"text":"버터에 마늘·고추를 볶는다."},{"text":"홍합과 맥주(또는 막걸리)를 붓고 뚜껑 덮어 찐다.","timerSec":300},{"text":"입이 벌어지면 파슬리를 뿌린다."}]'::jsonb, null, 'manual'),
  ('chamnamul_muchim', '참나물무침', 10, 1, 1, '{}'::text[], '[{"text":"참나물을 소금물에 살짝 데쳐 찬물에 헹군다.","timerSec":20},{"text":"물기를 짜고 간장·마늘·참기름·깨에 무친다."}]'::jsonb, null, 'manual'),
  ('chwinamul_bokkeum', '취나물볶음', 15, 1, 1, '{}'::text[], '[{"text":"취나물을 데쳐 찬물에 헹구고 물기를 짠다.","timerSec":60},{"text":"들기름에 마늘과 취나물을 볶는다."},{"text":"국간장으로 간하고 물 2큰술을 넣어 부드럽게 볶는다."}]'::jsonb, null, 'manual'),
  ('spring_greens_geotjeori', '봄동겉절이', 10, 1, 1, '{}'::text[], '[{"text":"봄동을 한 잎씩 떼어 씻고 먹기 좋게 뜯는다."},{"text":"고춧가루·액젓·마늘·설탕·매실청을 섞는다."},{"text":"먹기 직전에 봄동에 버무리고 참기름을 두른다."}]'::jsonb, null, 'manual'),
  ('deodeok_gui', '더덕구이', 30, 1, 1, '{}'::text[], '[{"text":"더덕 껍질을 벗기고 반 갈라 방망이로 두드려 편다."},{"text":"참기름·간장을 발라 애벌로 굽는다."},{"text":"고추장·설탕·마늘로 만든 양념을 발라 타지 않게 굽는다."}]'::jsonb, null, 'manual'),
  ('bamboo_shoot_bokkeum', '죽순볶음', 15, 1, 1, '{}'::text[], '[{"text":"죽순을 얇게 썰어 끓는 물에 데친다."},{"text":"들기름에 마늘·소고기를 볶다가 죽순을 넣는다."},{"text":"간장으로 간하고 깨를 뿌린다."}]'::jsonb, null, 'manual'),
  ('garlic_stem_bokkeum', '마늘종볶음', 15, 1, 1, '{}'::text[], '[{"text":"마늘종을 4cm 길이로 썬다."},{"text":"기름에 마늘종을 볶다가 건새우를 넣는다."},{"text":"간장·올리고당을 넣고 윤기 나게 볶는다."}]'::jsonb, null, 'manual'),
  ('dried_shrimp_bokkeum', '건새우볶음', 10, 1, 1, '{}'::text[], '[{"text":"마른 팬에 건새우를 볶아 비린내를 날린다."},{"text":"기름·마늘을 넣고 볶다가 간장·올리고당을 넣는다."},{"text":"윤기 나게 볶아 깨를 뿌린다."}]'::jsonb, null, 'manual'),
  ('hijiki_tofu_muchim', '톳두부무침', 15, 1, 1, '{}'::text[], '[{"text":"톳을 데쳐 찬물에 헹구고 먹기 좋게 썬다.","timerSec":60},{"text":"두부를 데쳐 면보로 물기를 짜며 으깬다."},{"text":"톳·두부를 소금·마늘·참기름·깨로 무친다."}]'::jsonb, null, 'manual'),
  ('green_laver_muchim', '파래무침', 15, 1, 1, '{}'::text[], '[{"text":"파래를 소금물에 주물러 씻고 물기를 짠다."},{"text":"무를 가늘게 채 썬다."},{"text":"식초·설탕·소금·마늘로 무친다."}]'::jsonb, null, 'manual'),
  ('wood_ear_bokkeum', '목이버섯 달걀볶음', 20, 1, 1, '{}'::text[], '[{"text":"목이버섯을 물에 30분 불려 먹기 좋게 뜯는다."},{"text":"달걀을 스크램블해 덜어 둔다."},{"text":"마늘·양파·목이버섯을 볶고 굴소스로 간한 뒤 달걀을 섞는다."}]'::jsonb, null, 'manual'),
  ('yam_gui', '마 들기름구이', 15, 1, 1, '{}'::text[], '[{"text":"마 껍질을 벗겨 1cm 두께로 썬다."},{"text":"들기름에 앞뒤로 노릇하게 굽는다.","timerSec":360},{"text":"소금이나 꿀을 곁들인다."}]'::jsonb, null, 'manual'),
  ('beet_pickle', '비트 피클', 20, 1, 1, '{}'::text[], '[{"text":"비트와 무를 한입 크기로 썬다."},{"text":"물 200ml·식초·설탕·소금을 끓인다."},{"text":"뜨거운 피클물을 붓고 식혀 냉장고에서 하루 둔다."}]'::jsonb, null, 'manual'),
  ('oiji_muchim', '오이지무침', 10, 1, 1, '{}'::text[], '[{"text":"오이지를 얇게 썰어 찬물에 담가 짠기를 뺀다."},{"text":"물기를 꼭 짠다."},{"text":"고춧가루·마늘·파·참기름·깨에 무친다."}]'::jsonb, null, 'manual'),
  ('carrot_rapee', '당근 라페', 15, 1, 1, '{}'::text[], '[{"text":"당근을 가늘게 채 썰어 소금에 10분 절이고 물기를 짠다."},{"text":"식초·올리브유·머스터드·꿀을 섞는다."},{"text":"당근·건포도를 버무려 하루 숙성한다."}]'::jsonb, null, 'manual'),
  ('cauliflower_roast', '콜리플라워 구이', 25, 1, 1, array['air_fryer']::text[], '[{"text":"콜리플라워를 송이로 나눈다."},{"text":"기름·소금에 버무린다."},{"text":"에어프라이어 190도에서 굽는다.","timerSec":900},{"text":"파마산을 뿌린다."}]'::jsonb, null, 'manual'),
  ('bindaetteok', '녹두전', 40, 1, 2, '{}'::text[], '[{"text":"녹두를 6시간 불려 껍질을 벗긴다."},{"text":"물 100ml와 함께 갈아 반죽을 만든다."},{"text":"다진 김치·숙주·고기·파를 섞고 소금으로 간한다."},{"text":"기름을 넉넉히 둘러 앞뒤로 바삭하게 부친다.","timerSec":480}]'::jsonb, null, 'manual'),
  ('chickpea_curry', '병아리콩 카레', 40, 1, 2, '{}'::text[], '[{"text":"병아리콩을 하룻밤 불려 삶는다.","timerSec":1500},{"text":"양파를 갈색이 나도록 볶는다."},{"text":"홀토마토·감자·병아리콩과 물 400ml를 넣고 끓인다.","timerSec":600},{"text":"카레를 풀고 시금치를 넣어 한소끔 끓인다."}]'::jsonb, null, 'manual'),
  ('caprese', '카프레제', 10, 1, 1, '{}'::text[], '[{"text":"토마토와 치즈를 비슷한 두께로 썬다."},{"text":"번갈아 담고 바질을 끼운다."},{"text":"올리브유·발사믹·소금을 뿌린다."}]'::jsonb, null, 'manual'),
  ('ricotta_salad', '리코타 치즈 샐러드', 10, 1, 1, '{}'::text[], '[{"text":"채소를 씻어 물기를 턴다."},{"text":"방울토마토·무화과를 썰어 올린다."},{"text":"리코타·견과류를 올리고 꿀·발사믹을 뿌린다."}]'::jsonb, null, 'manual'),
  ('smoked_salmon_salad', '훈제연어 샐러드', 10, 1, 1, '{}'::text[], '[{"text":"양파를 얇게 썰어 찬물에 담가 매운맛을 뺀다."},{"text":"채소·양파·무순 위에 연어를 올린다."},{"text":"올리브유·레몬즙·머스터드를 섞어 뿌린다."}]'::jsonb, null, 'manual'),
  ('iceberg_salad', '양상추 샐러드', 10, 1, 1, '{}'::text[], '[{"text":"양상추를 손으로 뜯어 찬물에 담갔다가 물기를 뺀다."},{"text":"오이·맛살·옥수수를 올린다."},{"text":"마요네즈·케첩을 섞어 뿌린다."}]'::jsonb, null, 'manual'),
  ('shakshuka', '샥슈카', 25, 1, 1, '{}'::text[], '[{"text":"양파·파프리카·마늘·소시지를 볶는다."},{"text":"토마토를 넣고 걸쭉하게 졸인다.","timerSec":600},{"text":"홈을 파서 달걀을 깨 넣고 뚜껑 덮어 익힌다.","timerSec":300},{"text":"치즈를 올리고 빵을 곁들인다."}]'::jsonb, null, 'manual'),
  ('hot_dog', '핫도그', 10, 1, 1, '{}'::text[], '[{"text":"소시지에 칼집을 내 굽는다."},{"text":"빵을 반 갈라 살짝 굽는다."},{"text":"소시지·다진 양파·피클을 넣고 케첩·머스터드를 뿌린다."}]'::jsonb, null, 'manual'),
  ('homemade_burger', '수제버거', 25, 1, 1, '{}'::text[], '[{"text":"다진 고기에 소금·후추를 넣고 치대 패티를 빚는다."},{"text":"앞뒤로 굽고 치즈를 올려 녹인다.","timerSec":360},{"text":"빵을 굽고 양상추·토마토·패티·양파·피클을 쌓는다."}]'::jsonb, null, 'manual'),
  ('air_fryer_fries', '에어프라이어 감자튀김', 20, 1, 1, array['air_fryer']::text[], '[{"text":"감자튀김을 펼쳐 에어프라이어 200도에서 굽는다.","timerSec":480},{"text":"흔들어 섞고 더 굽는다.","timerSec":420},{"text":"소금·파마산을 뿌리고 케첩을 곁들인다."}]'::jsonb, null, 'manual'),
  ('bagel_cream_cheese', '베이글 크림치즈', 5, 1, 1, '{}'::text[], '[{"text":"베이글을 반 갈라 굽는다."},{"text":"크림치즈를 바른다."},{"text":"훈제연어·양파를 올리거나 잼을 곁들인다."}]'::jsonb, null, 'manual'),
  ('garlic_bread', '마늘빵', 15, 1, 1, array['air_fryer']::text[], '[{"text":"말랑한 버터에 마늘·설탕·파슬리를 섞는다."},{"text":"빵을 썰어 마늘버터를 바른다."},{"text":"에어프라이어 170도에서 굽는다.","timerSec":360}]'::jsonb, null, 'manual'),
  ('bruschetta', '토마토 브루스케타', 15, 1, 1, '{}'::text[], '[{"text":"바게트를 썰어 노릇하게 굽는다."},{"text":"토마토를 잘게 썰어 마늘·올리브유·소금·바질과 섞는다."},{"text":"빵 위에 올리고 발사믹을 뿌린다."}]'::jsonb, null, 'manual'),
  ('hotcake', '핫케이크', 20, 1, 1, '{}'::text[], '[{"text":"가루·달걀·우유를 덩어리 없이 섞는다."},{"text":"약불에 국자로 부어 기포가 올라오면 뒤집는다.","timerSec":180},{"text":"버터·꿀·블루베리를 올린다."}]'::jsonb, null, 'manual'),
  ('peanut_butter_banana_toast', '땅콩버터 바나나 토스트', 5, 1, 1, '{}'::text[], '[{"text":"빵을 굽는다."},{"text":"땅콩버터를 바르고 바나나를 썰어 올린다."},{"text":"꿀·시나몬을 뿌린다."}]'::jsonb, null, 'manual'),
  ('cereal_bowl', '시리얼 요거트볼', 3, 1, 1, '{}'::text[], '[{"text":"그릇에 요거트나 우유를 담는다."},{"text":"시리얼과 과일을 올리고 꿀을 뿌린다."}]'::jsonb, null, 'manual'),
  ('fruit_smoothie', '과일 스무디', 5, 1, 1, '{}'::text[], '[{"text":"과일을 썬다."},{"text":"요거트(또는 우유)·꿀과 함께 곱게 간다. 얼린 과일을 쓰면 더 시원하다."}]'::jsonb, null, 'manual'),
  ('grapefruit_ade', '자몽 에이드', 5, 1, 1, '{}'::text[], '[{"text":"자몽 과육을 발라 즙을 낸다."},{"text":"꿀이나 설탕과 섞고 탄산수를 붓는다. 얼음을 넣는다."}]'::jsonb, null, 'manual'),
  ('dalgona_coffee', '달고나 커피', 10, 1, 1, '{}'::text[], '[{"text":"인스턴트커피·설탕·뜨거운 물 2큰술을 연한 갈색이 될 때까지 거품 낸다."},{"text":"얼음 넣은 우유 위에 올린다."}]'::jsonb, null, 'manual'),
  ('chocolate_banana_toast', '초코 바나나 토스트', 10, 1, 1, array['air_fryer']::text[], '[{"text":"빵에 버터를 바르고 초콜릿을 올린다."},{"text":"바나나를 썰어 올린다."},{"text":"에어프라이어 170도에서 초콜릿이 녹을 때까지 굽는다.","timerSec":240}]'::jsonb, null, 'manual'),
  ('melon_bowl', '참외·멜론 화채', 10, 1, 2, '{}'::text[], '[{"text":"과일을 한입 크기로 썰거나 스쿱으로 뜬다."},{"text":"탄산수에 꿀을 녹인다."},{"text":"과일을 담고 얼음을 띄운다."}]'::jsonb, null, 'manual')
