on conflict (id) do update set
  name = excluded.name,
  minutes = excluded.minutes,
  difficulty = excluded.difficulty,
  servings = excluded.servings,
  tools = excluded.tools,
  steps = excluded.steps,
  image_key = excluded.image_key,
  source = excluded.source;

